import { describe, expect, it } from "vitest";
import { getKnowledgeIndex } from "../knowledge/index.js";
import { searchPassages, tokenize } from "../knowledge/search.js";
import { FORBIDDEN_EVERYWHERE, RED_LINES } from "../knowledge/facts.js";
import { askFabrica } from "../tools/knowledge.js";

/**
 * The knowledge index is generated by scripts/build-knowledge.mjs and committed. These
 * tests guard its shape, that retrieval finds the right page for the questions people
 * ask most, and that the top passages never carry a phrasing Fabrica's wording rules forbid.
 */

const index = getKnowledgeIndex();

describe("knowledge index", () => {
  it("covers the three sources with a sensible number of passages", () => {
    const bySource = new Map<string, number>();
    for (const passage of index.passages) bySource.set(passage.source, (bySource.get(passage.source) ?? 0) + 1);
    expect(bySource.get("docs") ?? 0).toBeGreaterThan(100);
    expect(bySource.get("help") ?? 0).toBeGreaterThan(50);
    expect(bySource.get("trust-agreement") ?? 0).toBeGreaterThan(10);
    expect(index.sources.docs.documents).toBeGreaterThan(30);
    expect(index.sources.help.documents).toBeGreaterThan(30);
  });

  it("gives every passage a public URL and some text", () => {
    for (const passage of index.passages) {
      expect(passage.url, passage.id).toMatch(/^https:\/\/(docs\.fabrica\.land|help\.fabrica\.land|github\.com\/fabrica-land)\//);
      expect(passage.text.length, passage.id).toBeGreaterThan(20);
      expect(passage.text.length, passage.id).toBeLessThan(6000);
    }
  });

  it("has unique passage ids", () => {
    expect(new Set(index.passages.map((passage) => passage.id)).size).toBe(index.passages.length);
  });

  it("stays under the size budget", () => {
    expect(JSON.stringify(index).length).toBeLessThan(2 * 1024 * 1024);
  });

  it("never contains phrasings forbidden everywhere", () => {
    for (const passage of index.passages) {
      const lower = passage.text.toLowerCase();
      for (const phrase of FORBIDDEN_EVERYWHERE) expect(lower, `${passage.url} contains "${phrase}"`).not.toContain(phrase);
    }
  });
});

describe("tokenize", () => {
  it("normalizes Fabrica's compound terms and drops stopwords", () => {
    expect(tokenize("How do I start an on-ramp for my pre-minted token?")).toEqual(["start", "onramp", "premint", "token"]);
    expect(tokenize("the beneficial interest in the trust")).toEqual(["beneficialinterest", "trust"]);
  });
});

describe("retrieval", () => {
  const expectations: { question: string; urlIncludes: string[] }[] = [
    { question: "What does Fabrica cost?", urlIncludes: ["what-does-fabrica-cost"] },
    { question: "How do I add my property to Fabrica?", urlIncludes: ["how-do-i-add-my-property-to-fabrica"] },
    { question: "How does the Fabrica trust work and who is the trustee?", urlIncludes: ["fabrica-trust"] },
    { question: "What are Property checks?", urlIncludes: ["confidence-scoring-system"] },
    { question: "How does pool based lending work?", urlIncludes: ["lending"] },
    { question: "What happens to my property taxes?", urlIncludes: ["taxes"] },
    { question: "Can I use Fabrica from my AI assistant?", urlIncludes: ["ai"] },
    { question: "How do I remove my property from Fabrica?", urlIncludes: ["remove"] },
    { question: "Is a Fabrica token a security?", urlIncludes: ["securities"] },
    { question: "How do I make an offer on a property?", urlIncludes: ["offer"] },
    { question: "What happens when the owner dies?", urlIncludes: ["death"] },
    { question: "What is a beneficial interest?", urlIncludes: ["glossary", "fabrica-trust", "us-trust-agreement"] },
    { question: "Where is the contract code?", urlIncludes: ["build-on-fabrica"] },
    { question: "Are the smart contracts open source?", urlIncludes: ["build-on-fabrica"] },
  ];

  for (const expectation of expectations) {
    it(`finds the page for "${expectation.question}"`, () => {
      const hits = searchPassages(index.passages, expectation.question, { limit: 5 });
      expect(hits.length).toBeGreaterThan(0);
      const urls = hits.map((hit) => hit.passage.url);
      expect(urls.some((url) => expectation.urlIncludes.some((part) => url.includes(part))), urls.join("\n")).toBe(true);
    });
  }

  it("returns at most one hit per page section", () => {
    const hits = searchPassages(index.passages, "trustee duties", { limit: 5 });
    const keys = hits.map((hit) => `${hit.passage.url}#${hit.passage.sectionTitle}`);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it("filters by source", () => {
    const hits = searchPassages(index.passages, "trustee duties", { limit: 5, source: "trust-agreement" });
    expect(hits.length).toBeGreaterThan(0);
    for (const hit of hits) expect(hit.passage.source).toBe("trust-agreement");
  });

  it("returns nothing for a question made of stopwords", () => {
    expect(searchPassages(index.passages, "what is it", { limit: 5 })).toEqual([]);
  });
});

describe("red lines", () => {
  for (const redLine of RED_LINES) {
    it(`holds for "${redLine.question}"`, () => {
      const hits = searchPassages(index.passages, redLine.question, { limit: 5 });
      expect(hits.length).toBeGreaterThan(0);
      const combined = hits.map((hit) => `${hit.passage.title} ${hit.passage.sectionTitle} ${hit.passage.text}`).join("\n").toLowerCase();
      expect(redLine.mustContainOneOf.some((phrase) => combined.includes(phrase.toLowerCase())), combined.slice(0, 500)).toBe(true);
      for (const phrase of redLine.mustNotContain) expect(combined).not.toContain(phrase.toLowerCase());
    });
  }
});

describe("ask_fabrica", () => {
  it("returns cited passages, the index provenance and a note", async () => {
    const result = await askFabrica({ question: "What does Fabrica cost?" });
    if ("error" in result) throw new Error(result.error);
    expect(result.passages.length).toBeGreaterThan(0);
    expect(result.passages[0].url).toMatch(/^https:\/\//);
    expect(result.index.builtAt).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(result.note).toContain("not legal, tax or financial advice");
  });

  it("suggests lookup tools when the question is really a lookup", async () => {
    const result = await askFabrica({ question: "Show me property 12743610130101631987" });
    if ("error" in result) throw new Error(result.error);
    expect(result.suggestedTools).toContain("get_property");
  });

  it("caps the passage count and respects the source filter", async () => {
    const result = await askFabrica({ question: "trustee", maxPassages: 50, source: "help" });
    if ("error" in result) throw new Error(result.error);
    expect(result.passages.length).toBeLessThanOrEqual(10);
    for (const passage of result.passages) expect(passage.source).toBe("help");
  });

  it("rejects an empty question", async () => {
    const result = await askFabrica({ question: "  " });
    expect("error" in result).toBe(true);
  });
});
